{
  "items": [
    {
      "name": "Finsupp.apply_linearCombination_id",
      "module_name": "Mathlib.LinearAlgebra.Finsupp.LinearCombination",
      "kind": "theorem",
      "type": "∀ {M : Type u_2} (R : Type u_5) [inst : Semiring R] [inst_1 : AddCommMonoid M] [inst_2 : Module R M] {M' : Type u_8}\n  [inst_3 : AddCommMonoid M'] [inst_4 : Module R M'] (f : M →ₗ[R] M') (l : M →₀ R),\n  f ((Finsupp.linearCombination R id) l) = (Finsupp.linearCombination R ⇑f) l"
    },
    {
      "name": "LinearMap.map_finsupp_linearCombination",
      "module_name": "Mathlib.LinearAlgebra.Finsupp.LinearCombination",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {M : Type u_2} {N : Type u_3} [inst : Semiring R] [inst_1 : AddCommMonoid M] [inst_2 : Module R M]\n  [inst_3 : AddCommMonoid N] [inst_4 : Module R N] (f : M →ₗ[R] N) {ι : Type u_4} {g : ι → M} (l : ι →₀ R),\n  f ((Finsupp.linearCombination R g) l) = (Finsupp.linearCombination R (⇑f ∘ g)) l"
    },
    {
      "name": "Finsupp.apply_linearCombination",
      "module_name": "Mathlib.LinearAlgebra.Finsupp.LinearCombination",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_2} (R : Type u_5) [inst : Semiring R] [inst_1 : AddCommMonoid M] [inst_2 : Module R M]\n  {M' : Type u_8} [inst_3 : AddCommMonoid M'] [inst_4 : Module R M'] (f : M →ₗ[R] M') (v : α → M) (l : α →₀ R),\n  f ((Finsupp.linearCombination R v) l) = (Finsupp.linearCombination R (⇑f ∘ v)) l"
    },
    {
      "name": "Finsupp.mapRange.linearMap_apply",
      "module_name": "Mathlib.LinearAlgebra.Finsupp.Defs",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_2} {N : Type u_3} {R : Type u_5} {R₂ : Type u_6} [inst : Semiring R] [inst_1 : Semiring R₂]\n  [inst_2 : AddCommMonoid M] [inst_3 : Module R M] [inst_4 : AddCommMonoid N] [inst_5 : Module R₂ N] {σ₁₂ : R →+* R₂}\n  (f : M →ₛₗ[σ₁₂] N) (g : α →₀ M), (Finsupp.mapRange.linearMap f) g = Finsupp.mapRange ⇑f ⋯ g"
    },
    {
      "name": "Finsupp.mapRange.linearMap",
      "module_name": "Mathlib.LinearAlgebra.Finsupp.Defs",
      "kind": "definition",
      "type": "{α : Type u_1} →\n  {M : Type u_2} →\n    {N : Type u_3} →\n      {R : Type u_5} →\n        {R₂ : Type u_6} →\n          [inst : Semiring R] →\n            [inst_1 : Semiring R₂] →\n              [inst_2 : AddCommMonoid M] →\n                [inst_3 : Module R M] →\n                  [inst_4 : AddCommMonoid N] →\n                    [inst_5 : Module R₂ N] → {σ₁₂ : R →+* R₂} → (M →ₛₗ[σ₁₂] N) → (α →₀ M) →ₛₗ[σ₁₂] α →₀ N"
    },
    {
      "name": "DFinsupp.mapRange.linearMap_apply",
      "module_name": "Mathlib.LinearAlgebra.DFinsupp",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {R : Type u_3} [inst : Semiring R] {β₁ : ι → Type u_8} {β₂ : ι → Type u_9}\n  [inst_1 : (i : ι) → AddCommMonoid (β₁ i)] [inst_2 : (i : ι) → AddCommMonoid (β₂ i)]\n  [inst_3 : (i : ι) → Module R (β₁ i)] [inst_4 : (i : ι) → Module R (β₂ i)] (f : (i : ι) → β₁ i →ₗ[R] β₂ i)\n  (x : Π₀ (i : ι), β₁ i), (DFinsupp.mapRange.linearMap f) x = DFinsupp.mapRange (fun i x => (f i) x) ⋯ x"
    }
  ]
}

